SELECT c.company_id AS companyId, c.company_abbreviation AS companyAbbreviation FROM basic_v2_department_management d INNER JOIN basic_v2_company_management c ON d.company_id = c.company_id WHERE d.active_flg = 1 AND d.department_id IN
#{departmentId}
AND c.active_flg = 1 AND c.sale_or_procurement = 1;

SELECT c.company_id AS companyId, c.company_abbreviation AS companyAbbreviation FROM basic_v2_department_management d INNER JOIN basic_v2_company_management c ON d.company_id = c.company_id WHERE d.active_flg = 1 AND d.department_id IN
#{departmentId}
AND c.active_flg = 1 AND c.sale_or_procurement = 3;

SELECT c.company_id AS companyId, c.company_abbreviation AS companyAbbreviation FROM basic_v2_project_manage p INNER JOIN basic_v2_company_management c ON p.sales_company_id = c.company_id WHERE p.active_flg = 1 AND p.project_id IN
#{projectId}
AND c.active_flg = 1 AND c.sale_or_procurement IN (1, 3);
